// This code has been fully generated by an AI.
//
// Health page: one small time chart per metric. Charts and series come from
// the server; colors are CSS custom properties so both themes work.

import uPlot from "./vendor/uplot-1.6.32/uPlot.esm.js";
import { axisStyle, withAlpha } from "./theme-data.js";
import { chartColors, onThemeChange } from "./theme.js";

const num = (v, d = 1) => (v == null ? "–" : v.toLocaleString("de-DE", { maximumFractionDigits: d }));
const day = (s) => new Date(s * 1000).toLocaleDateString("de-DE", { day: "numeric", month: "short", year: "2-digit", timeZone: "UTC" });

export function showHealth() {
  const data = JSON.parse(document.getElementById("health-data").textContent);
  const root = document.getElementById("health-charts");
  if (!data.days?.length) return;
  let plots = draw(root, data);
  onThemeChange(() => {
    plots.forEach((p) => p.destroy());
    plots = draw(root, data);
  });
}

function draw(root, data) {
  root.replaceChildren();
  const colors = chartColors();
  const css = getComputedStyle(document.documentElement);
  const color = (name) => css.getPropertyValue(name).trim() || colors.accent;
  const sync = uPlot.sync("health");
  const plots = [];
  for (const c of data.charts) {
    const card = document.createElement("section");
    card.className = "card health-chart";
    const head = document.createElement("header");
    const title = document.createElement("h2");
    title.textContent = c.unit ? `${c.title} (${c.unit})` : c.title;
    const out = document.createElement("output");
    head.append(title, out);
    const box = document.createElement("div");
    card.append(head, box);
    root.append(card);

    const values = c.series.map((s) => data.values[s.key]);
    const lastIdx = (() => {
      for (let i = data.days.length - 1; i >= 0; i--) if (values.some((v) => v[i] != null)) return i;
      return data.days.length - 1;
    })();
    const show = (i) => {
      if (i == null) i = lastIdx;
      const parts = c.series.filter((s) => !s.dash).map((s) => num(data.values[s.key][i], c.unit === "h" ? 1 : 0));
      out.textContent = `${day(data.days[i])}: ${parts.join(" · ")}`;
    };
    show(null);
    const plot = new uPlot({
      width: box.clientWidth || root.clientWidth,
      height: 130,
      legend: { show: false },
      cursor: { sync: { key: sync.key }, drag: { x: false, y: false }, points: { size: 6 } },
      scales: { x: { time: true } },
      axes: [
        axisStyle(colors, {
          size: 26,
          values: (u, ticks) => ticks.map((t) => new Date(t * 1000).toLocaleDateString("de-DE", { day: "numeric", month: "short", timeZone: "UTC" })),
        }),
        // Width follows the longest label (steps reach "12.000").
        axisStyle(colors, {
          size: (u, values) => (values ? Math.max(3, ...values.map((v) => v.length)) * 7 + 16 : 42),
          values: (u, t) => t.map((v) => num(v, 1)),
        }),
      ],
      series: [
        {},
        ...c.series.map((s) => {
          const col = color(s.color);
          if (c.bars) {
            return { stroke: col, fill: withAlpha(col, 0.75), paths: uPlot.paths.bars({ size: [0.8, 10] }), points: { show: false } };
          }
          return { stroke: col, width: s.dash ? 1 : 1.75, dash: s.dash ? [4, 4] : undefined, spanGaps: true, points: { show: false } };
        }),
      ],
      hooks: { setCursor: [(u) => show(u.cursor.idx)] },
    }, [data.days, ...values], box);
    const resize = new ResizeObserver(() => plot.setSize({ width: box.clientWidth, height: 130 }));
    resize.observe(box);
    plots.push({ destroy() { resize.disconnect(); plot.destroy(); } });
  }
  return plots;
}
